import { definePlugin } from '#calm';
import { settings } from './s3.js';

export default definePlugin({
  name: 'storage-s3',
  env: {
    S3_BUCKET: 'Bucket for uploads',
    S3_REGION: 'Bucket region (default us-east-1)',
    S3_ACCESS_KEY_ID: 'Access key id; without it the AWS default credential chain is used',
    S3_SECRET_ACCESS_KEY: { secret: true, description: 'Secret access key' },
    S3_ENDPOINT: 'Endpoint for S3 compatible storage (R2, MinIO...)',
    UPLOAD_MAX_MB: 'Largest upload in MB (default 10)',
    UPLOAD_ALLOWED_TYPES: 'Comma separated MIME types (default: images and PDF)',
  },
  setup(calm) {
    calm.doctor(() => {
      const s = settings();
      const findings = [];
      if (!s.bucket) findings.push({ level: 'error', id: 's3-bucket', title: 'S3_BUCKET is not set', detail: 'Uploads cannot work without a bucket. Set S3_BUCKET (and S3_ENDPOINT for R2/MinIO).' });
      if (!process.env.S3_ACCESS_KEY_ID && calm.config.mode !== 'production') {
        findings.push({ level: 'info', id: 's3-credentials', title: 'No S3_ACCESS_KEY_ID set', detail: 'The AWS default credential chain will be used (IAM role, profile or AWS_* env vars).' });
      }
      return findings;
    });
    calm.devtools.panel('storage', () => {
      const s = settings();
      return { driver: 's3', bucket: s.bucket ?? '(not set)', region: s.region, endpoint: s.endpoint ?? 'AWS', maxMb: s.maxBytes / 1048576, allowedTypes: s.allowed };
    });
  },
});

import { randomUUID } from 'node:crypto';
import { S3Client, PutObjectCommand, GetObjectCommand, HeadObjectCommand, DeleteObjectCommand } from '@aws-sdk/client-s3';
import { getSignedUrl } from '@aws-sdk/s3-request-presigner';

// S3 (or any S3-compatible store) with presigned URLs: file bytes never pass
// through your API servers. Objects are private; downloads use short-lived URLs.

export const settings = () => ({
  bucket: process.env.S3_BUCKET,
  region: process.env.S3_REGION || 'us-east-1',
  endpoint: process.env.S3_ENDPOINT || undefined,
  maxBytes: Number(process.env.UPLOAD_MAX_MB || 10) * 1024 * 1024,
  allowed: (process.env.UPLOAD_ALLOWED_TYPES || 'image/png,image/jpeg,image/gif,image/webp,application/pdf').split(',').map((s) => s.trim()),
  uploadTtl: 600,
  downloadTtl: 300,
});

let client;
export function s3() {
  const s = settings();
  client ??= new S3Client({
    region: s.region,
    endpoint: s.endpoint,
    forcePathStyle: Boolean(s.endpoint),
    credentials: process.env.S3_ACCESS_KEY_ID
      ? { accessKeyId: process.env.S3_ACCESS_KEY_ID, secretAccessKey: process.env.S3_SECRET_ACCESS_KEY }
      : undefined, // fall back to the default AWS credential chain (IAM roles, env, profiles)
  });
  return client;
}

const EXT = { 'image/png': 'png', 'image/jpeg': 'jpg', 'image/gif': 'gif', 'image/webp': 'webp', 'application/pdf': 'pdf' };

export const newKey = (ownerId, contentType) => {
  const d = new Date();
  return `uploads/${ownerId}/${d.getUTCFullYear()}/${String(d.getUTCMonth() + 1).padStart(2, '0')}/${randomUUID()}.${EXT[contentType] ?? 'bin'}`;
};

export async function presignUpload(key, contentType, size) {
  const s = settings();
  const command = new PutObjectCommand({ Bucket: s.bucket, Key: key, ContentType: contentType, ContentLength: size });
  const url = await getSignedUrl(s3(), command, { expiresIn: s.uploadTtl, signableHeaders: new Set(['content-type', 'content-length']) });
  return { url, method: 'PUT', headers: { 'Content-Type': contentType }, expiresIn: s.uploadTtl };
}

export async function head(key) {
  try {
    return await s3().send(new HeadObjectCommand({ Bucket: settings().bucket, Key: key }));
  } catch (err) {
    if (err?.$metadata?.httpStatusCode === 404 || err?.name === 'NotFound') return null;
    throw err;
  }
}

export async function presignDownload(key, fileName, inline) {
  const s = settings();
  const command = new GetObjectCommand({
    Bucket: s.bucket,
    Key: key,
    ResponseContentDisposition: `${inline ? 'inline' : 'attachment'}; filename*=UTF-8''${encodeURIComponent(fileName)}`,
  });
  return getSignedUrl(s3(), command, { expiresIn: s.downloadTtl });
}

export const remove = (key) => s3().send(new DeleteObjectCommand({ Bucket: settings().bucket, Key: key }));

import { resource, f } from '#calm';

// Uploaded files (metadata). Created through POST /api/files/presign, confirmed with
// POST /api/files/:id/complete once the browser has PUT the bytes to S3.
export default resource('file', {
  crud: ['list', 'read', 'delete'],
  fields: {
    originalName: f.string().readOnly().searchable().sortable(),
    mimeType: f.string().readOnly().filterable(),
    size: f.integer().readOnly().sortable(),
    status: f.enum(['pending', 'ready']).default('pending').readOnly().filterable(),
    key: f.string().hidden(),
    owner: f.ref('user').owner().filterable(),
  },
  policy: {
    list: 'owner | admin',
    read: 'owner | admin',
    create: 'authenticated',
    update: 'none',
    delete: 'owner | admin',
  },
});

import { f, badRequest } from '#calm';
import { settings, newKey, presignUpload, presignDownload, head } from '#app/blocks/storage-s3/s3.js';

const INLINE = new Set(['image/png', 'image/jpeg', 'image/gif', 'image/webp']);

export default (r) => {
  r.post(
    '/presign',
    {
      policy: 'authenticated',
      status: 201,
      summary: 'Start an upload: returns a presigned PUT URL',
      input: { fileName: f.string().required().max(255), contentType: f.string().required().max(100), size: f.integer().required().min(1) },
    },
    async (ctx) => {
      const s = settings();
      const { fileName, contentType, size } = ctx.body;
      if (!s.allowed.includes(contentType)) throw badRequest(`File type ${contentType} is not allowed. Allowed: ${s.allowed.join(', ')}`);
      if (size > s.maxBytes) throw badRequest(`File is larger than ${Math.round(s.maxBytes / 1048576)} MB`);
      const key = newKey(ctx.user.id, contentType);
      const file = await ctx.service.create({ originalName: fileName, mimeType: contentType, size, key, status: 'pending' }, ctx);
      return { file: await ctx.serialize(file), upload: await presignUpload(key, contentType, size) };
    },
  );

  r.post('/:id/complete', { policy: 'owner', summary: 'Confirm an upload once the bytes are in S3' }, async (ctx) => {
    const doc = await ctx.service.model.findById(ctx.doc._id).select('+key').lean();
    if (doc.status === 'ready') return doc;
    const object = await head(doc.key);
    if (!object) throw badRequest('The file has not been uploaded yet');
    if (object.ContentLength !== doc.size || object.ContentType !== doc.mimeType) {
      throw badRequest('Uploaded object does not match the declared size or type');
    }
    return ctx.service.update(doc._id, { status: 'ready' }, ctx);
  });

  r.get('/:id/download', { policy: 'owner | admin', summary: 'Redirect to a short-lived download URL' }, async (ctx) => {
    const doc = await ctx.service.model.findById(ctx.doc._id).select('+key').lean();
    if (doc.status !== 'ready') throw badRequest('This file is not uploaded yet');
    ctx.res.redirect(302, await presignDownload(doc.key, doc.originalName, INLINE.has(doc.mimeType)));
  });
};

import { ResourceService } from '#calm';
import { remove } from '#app/blocks/storage-s3/s3.js';

export default class FileService extends ResourceService {
  async afterDelete(doc) {
    if (doc.key) await remove(doc.key).catch((err) => this.log.warn('Could not delete S3 object', { key: doc.key, err }));
  }
}
